{ "results": [ { "title": "消搖墟經", "verdict": "partial", "issue": "Biên giả thường ghi 洪自誠 (Hồng Tự Thành); «洪自成» là biến thể/dị tự. Thuộc Tục Đạo tạng Vạn Lịch thì đúng; «tiên truyện–tiểu dao chí» đúng hướng nhưng không phải kinh điển thuần túy." }, { "title": "上清黃氣陽精三道順行經", "verdict": "partial", "issue": "Biệt danh «藏天隱月» đúng. «託西城王君授魏華存» là khung truyền thụ Thượng Thanh phổ biến; chi tiết truyền thụ cụ thể của kinh này đôi khi ghi khác (Tây Thành Vương quân / các tầng tiên). Nội dung «thuận hành tam đạo / hoàng khí dương tinh» đúng hướng." }, { "title": "金蓮正宗仙源像傳", "verdict": "partial", "issue": "Tác giả thường ghi 劉志玄、謝西蟾 — đúng. Song song với 金蓮正宗記 (Tần Chí An) — đúng. Số chân và phạm vi tiểu truyện có thể biến thể theo bản; «Đông Hoa, Chính Dương, Thuần Dương và Thất Chân» là tóm tắt chuẩn nhưng không phải toàn bộ phả hệ trong mọi bản." }, { "title": "玄風慶會錄", "verdict": "partial", "issue": "Ký giả 移剌楚才／耶律楚材 — 移剌 là dị tự/họ Khitan; 耶律楚材 là tên chuẩn. Nội dung Khâu Xử Cơ trả lời Thành Cát Tư Hãn về dưỡng sinh đúng; «phản đối phục thực ngoại đan» là diễn giải hợp lý nhưng kinh/lục nhấn bảo tinh khí hơn là luận chiến ngoại đan tường minh." }, { "title": "圖經衍義本草", "verdict": "partial", "issue": "Hợp biên 證類本草/圖經 với 本草衍義 của Khấu Tông Thích; Hứa Hồng hiệu — hướng đúng. Số quyển trong Đạo Tạng (thường ~42 + tự lệ) cần đối chiếu đúng bản DZ; «唐慎微、寇宗奭» là quan hệ biên–diễn nghĩa, không phải đồng tác giả ngang hàng thuần túy." }, { "title": "孫真人備急千金要方", "verdict": "partial", "issue": "Tôn Tư Mạo và nội dung y phương đúng; «bộ y phương lớn nhất trong Đạo Tạng» là nhận định tương đối (có 千金翼方 và các dược thư lớn khác). Thu vào Thái Bình bộ — cần xác nhận mục lục cụ thể theo bản Chính thống." }, { "title": "西嶽華山誌", "verdict": "partial", "issue": "Vương Xử Nhất (Toàn Chân) tựa Kim Đại Định Quý Mão (1183) được nhiều nguồn ghi; tuy nhiên một số mục lục/ghi chú còn tranh luận biên giả vs. người viết tựa. Nội dung sơn chí Hoa Sơn đúng hướng." }, { "title": "混元八景真经", "verdict": "partial", "issue": "Năm quyển, nội dung hỗn nguyên bát cảnh / phòng trung–nội luyện được mô tả trong catalog; «gọi Huyền Vũ chứ không x…» (câu cắt cụt) dễ gây nhầm với 玄武 thần. Niên đại «nghi Đường–Ngũ Đại» là suy đoán học thuật, không chắc chắn." }, { "title": "紙舟先生全真直指", "verdict": "partial", "issue": "金月巖 biên, 黃公望 truyền — attribution phổ biến nhưng quan hệ biên/truyền đôi khi bị đảo trong nguồn phụ. «Thất phản thất chân» và nội dung nội đan Toàn chân đúng hướng." }, { "title": "太上说转轮五道宿命因缘经", "verdict": "partial", "issue": "Tồn tại trong Đạo Tạng, nội dung nghiệp báo năm đường / khung Phật hóa đúng hướng. «Komjathy/Pregadio xác nhận» là claim thư mục — đúng nếu trỏ catalog DZ, nhưng không tự chứng minh chi tiết nội dung essence." } ] }{ "results": [ { "title": "金闕帝君三元真一經", "verdict": "partial", "issue": "Trung nhất là «giáng cung đan hoàng» (絳宮之丹皇): thứ tự/cách diễn «đan hoàng giáng cung» dễ đọc nhầm 降 cung; cốt lõi thượng–trung–hạ nhất đúng. «Phân xuất từ Đại Hữu Diệu Kinh» đúng hướng thư mục." }, { "title": "周易參同契分章通真義", "verdict": "partial", "issue": "Bành Hiểu (Chân Nhất Tử), hậu Thục/Ngũ Đại — đúng. «Ảnh hưởng nhất thời Đường–Tống» hơi phóng đại: ông thuộc hậu Thục (không phải Đường), và là bản chú then chốt sớm nhất còn lại chứ không phải «nền cho mọi sớ giải sau» theo nghĩa tuyệt đối." } ] }{
  "results": [
    {
      "title": "消搖墟經",
      "verdict": "partial",
      "issue": "Biên giả chuẩn thường ghi 洪自誠 (Minh sơ); «洪自成» là dị tự/biến thể (một số bản mục lục dùng). Hai quyển, Tục Đạo tạng, tiên truyện–tiêu dao chí thì đúng."
    },
    {
      "title": "上清黃氣陽精三道順行經",
      "verdict": "partial",
      "issue": "Biệt danh 藏天隱月 đúng. «託西城王君授魏華存» là khung truyền thụ Thượng Thanh chung, không phải chỉ riêng kinh này (kinh mở bằng 南極上元君). Nội dung thuận hành tam đạo / hoàng khí dương tinh đúng hướng."
    },
    {
      "title": "太真玉帝四極明科經",
      "verdict": "partial",
      "issue": "Năm quyển, Tứ Cực Minh Khoa, tổng 120 điều, ngũ cung Thái Huyền — đúng. «Mỗi cung hai mươi điều» hơi cứng: nhiều mô tả ghi mỗi cung «二十馀条» (hơn hai mươi), cộng thành 120."
    },
    {
      "title": "周易參同契分章通真義",
      "verdict": "partial",
      "issue": "Bành Hiểu (Chân Nhất Tử) chú, chia chương — đúng. «Thời Đường–Tống» lệch: ông thuộc hậu Thục / Ngũ Đại. Bản chú then chốt sớm và ảnh hưởng lớn, nhưng «nền cho mọi sớ giải sau» là phóng đại."
    },
    {
      "title": "道法心傳",
      "verdict": "inaccurate",
      "issue": "Vương Duy Nhất là đạo sĩ Thần Tiêu (Nguyên), hợp phù lục–lôi pháp với nội đan/tâm pháp; không phải «hợp Toàn Chân nội tu với Chính Nhất lôi pháp». Gán Toàn Chân là sai hệ phái."
    },
    {
      "title": "西嶽華山誌",
      "verdict": "partial",
      "issue": "Tựa Đại Định Quý Mão (1183) và nội dung sơn chí Hoa Sơn đúng hướng. Tác giả «王處一» còn tranh: một nhánh ghi 蓮峰逸士 (khác Toàn Chân 玉陽子王處一), Wikipedia/một số nguồn gán cho ngọc dương tử — chỉ ghi tên dễ gộp nhầm hai người."
    },
    {
      "title": "地祇上將溫太保傳",
      "verdict": "partial",
      "issue": "Hoàng Công Cẩn hiệu/bổ, Ôn Quỳnh tự Tử Ngọc, Bình Dương Ôn Châu — đúng. Bản Đạo Tạng nhấn võ tướng (quân Quách Tử Nghi), Thái Sơn, cầu mưa, Trương Kế Tiên và địa kỳ pháp. «Nuốt thuốc ôn dịch thay dân» chủ yếu là huyền thoại dân gian (thần phả), không phải cốt lõi mô tả chuẩn của bản DZ."
    },
    {
      "title": "天隱子",
      "verdict": "partial",
      "issue": "Tám thiên (Thần tiên…Thần giải) và tư tưởng tiệm tiến đúng. Attribution: Tư Mã Thừa Trinh viết tựa bảo «bất tri hà hứa nhân»; thường gán cho ông nhưng sách để 天隱子 — «述» là an toàn nhưng không chắc tuyệt đối."
    },
    {
      "title": "混元八景真经",
      "verdict": "partial",
      "issue": "Năm quyển, hỗn nguyên chân nhân, nội đan / bổ khí dưỡng mệnh — đúng hướng catalog. «Thuật phòng trung» phóng đại: mục lục học thuật xếp nội đan, không phải kinh phòng trung. Câu «Gọi Huyền Vũ…» (cụt) dễ nhầm với 玄武; kinh xưng 混元."
    },
    {
      "title": "胎息精微论",
      "verdict": "partial",
      "issue": "Nội dung phản đối cưỡng bách bế khí, phân phàm tức / chân tức, thần ngự khí — đúng hướng. Tác giả 佚名; «hoặc thác hệ Tư Mã Thừa Trinh» là suy đoán truyền thống, không phải attribution chắc trong Đạo Tạng."
    }
  ]
}
